describe("sympy/simplify/tests/test_function.py", () => {
  it("test_attrs:10", () => {
    const v1 = new Dummy('a', {}, 1000000);
    expect(sympyMatches([at(new Hyper_Function([2, v1], [new Dummy('b', {}, 1000001)]).ap, 0), v1], '(2, _a)')).toBe(true);
  });
  it("test_attrs:11", () => {
    expect(sympyMatches([new Dummy('b', {}, 1000001)], '(_b,)')).toBe(true);
  });
  it("test_attrs:12", () => {
    expect(sympyStr([at(new Hyper_Function([2, new Dummy('a', {}, 1000000)], [new Dummy('b', {}, 1000001)]).args, 0), at(new Hyper_Function([2, new Dummy('a', {}, 1000000)], [new Dummy('b', {}, 1000001)]).args, 1)], 't')).toBe('((2, _a), (_b,))');
  });
  // a primitive result that no library call returned
  //   assert f.sizes == (2, 1)
  //   => (2, 1)
  it.todo("test_attrs:13");
  it("test_call:18", () => {
    expect(sympyStr(new Hyper_Function([2, new Dummy('a', {}, 1000001)], [new Dummy('b', {}, 1000002)]).call(new Dummy('x', {}, 1000000)))).toBe('hyper((2, _a), (_b,), _x)');
  });
  it("test_has:23", () => {
    expect(sympyStr(new Hyper_Function([2, new Mul([rational(-1), new Dummy('a', {}, 1000000)])], [new Dummy('b', {}, 1000001)]).has(new Dummy('a', {}, 1000000)))).toBe('True');
  });
  it("test_has:24", () => {
    expect(sympyStr(new Hyper_Function([2, new Mul([rational(-1), new Dummy('a', {}, 1000001)])], [new Dummy('b', {}, 1000000)]).has(Tuple(new Dummy('b', {}, 1000000))))).toBe('True');
  });
  it("test_has:25", () => {
    expect(sympyStr(new Hyper_Function([2, new Mul([rational(-1), new Dummy('a', {}, 1000001)])], [new Dummy('b', {}, 1000002)]).has(new Dummy('c', {}, 1000000)))).toBe('False');
  });
  it("test_eq:28", () => {
    expect(sympyStr(new Hyper_Function([1], []))).toBe('Hyper_Function((1,), ())');
  });
  it("test_eq:29", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("test_eq:30", () => {
    expect(sympyStr(new Hyper_Function([1], []))).not.toBe('Hyper_Function((2,), ())');
  });
  it("test_eq:31", () => {
    expect(sympyStr(new Hyper_Function([1], []))).not.toBe('Hyper_Function((1, 2), ())');
  });
  it("test_eq:32", () => {
    expect(sympyStr(new Hyper_Function([1], []))).not.toBe('Hyper_Function((1,), (2,))');
  });
  it("test_gamma:35", () => {
    expect(sympyStr(new Hyper_Function([2, 3], [-1]).gamma)).toBe('0');
  });
  it("test_gamma:36", () => {
    expect(sympyStr(new Hyper_Function([-2, -3], [-1]).gamma)).toBe('2');
  });
  it("test_gamma:38", () => {
    expect(sympyStr(new Hyper_Function([-1, new Dummy('Dummy_56256364870546', { integer: true }, 1000000), 1], []).gamma)).toBe('1');
  });
  it("test_gamma:39", () => {
    expect(sympyStr(new Hyper_Function([-1, new Mul([rational(-1), new Dummy('Dummy_56256364870546', { integer: true }, 1000000)]), 1], []).gamma)).toBe('1');
  });
  it("test_gamma:41", () => {
    expect(sympyStr(new Hyper_Function([-1, new Dummy('Dummy_56256364870547', { integer: true, positive: true }, 1000000), 1], []).gamma)).toBe('1');
  });
  it("test_gamma:42", () => {
    expect(sympyStr(new Hyper_Function([-1, new Mul([rational(-1), new Dummy('Dummy_56256364870547', { integer: true, positive: true }, 1000000)]), 1], []).gamma)).toBe('2');
  });
});
